import { useCallback, useEffect, useRef } from 'react';

const ISS_API    = 'https://api.wheretheiss.at/v1/satellites/25544';
const REFRESH_MS = 5_000;
const TRAIL_MAX  = 80; // keep last 80 positions (~7 min of history)

interface ISSData {
  latitude:  number;
  longitude: number;
  altitude:  number;   // km
  velocity:  number;   // km/h
  visibility: string;
}

interface ISSLayerProps {
  map:     import('leaflet').Map | null;
  enabled: boolean;
}

export function ISSLayer({ map, enabled }: ISSLayerProps) {
  const markerRef    = useRef<import('leaflet').Marker | null>(null);
  const trailRef     = useRef<import('leaflet').Polyline | null>(null);
  const positionsRef = useRef<[number, number][]>([]);

  const clearAll = useCallback(() => {
    markerRef.current?.remove();
    markerRef.current = null;
    trailRef.current?.remove();
    trailRef.current = null;
    positionsRef.current = [];
  }, []);

  const fetchAndRender = useCallback(async () => {
    if (!map || !enabled) return;

    try {
      const res = await fetch(ISS_API);
      if (!res.ok) return;
      const d = await res.json() as ISSData;
      if (!map || !enabled) return;

      const L   = window.L;
      const lat = d.latitude;
      const lng = d.longitude;

      // Accumulate trail — handle wrap-around at ±180°
      const prev = positionsRef.current;
      if (prev.length > 0) {
        const [, pLng] = prev[prev.length - 1];
        // If longitude jumps >180° the ISS wrapped; break the trail
        if (Math.abs(lng - pLng) > 180) positionsRef.current = [];
      }
      positionsRef.current = [...positionsRef.current, [lat, lng] as [number, number]].slice(-TRAIL_MAX);

      const iconHtml = `<div style="
        font-size:22px;
        filter:drop-shadow(0 0 8px rgba(255,210,0,.9));
        line-height:1;
      ">🛸</div>`;

      const icon = L.divIcon({ html: iconHtml, className: '', iconSize: [24, 24], iconAnchor: [12, 12] });

      const popup = `
        <div style="font-family:monospace;font-size:12px;line-height:1.75;min-width:160px;">
          <div style="font-weight:700;font-size:13px;color:#f0c040;margin-bottom:4px">🛸 ISS</div>
          <div>↑ ${Math.round(d.altitude).toLocaleString()} km</div>
          <div>→ ${Math.round(d.velocity).toLocaleString()} km/h</div>
          <div>☀ ${d.visibility}</div>
          <div style="margin-top:4px;opacity:.7;font-size:11px">
            ${lat.toFixed(3)}°, ${lng.toFixed(3)}°
          </div>
        </div>`;

      if (markerRef.current) {
        markerRef.current.setLatLng([lat, lng]);
        markerRef.current.getPopup()?.setContent(popup);
      } else {
        markerRef.current = L.marker([lat, lng], { icon, zIndexOffset: 2000 })
          .bindPopup(popup, { maxWidth: 210 })
          .addTo(map);
      }

      if (trailRef.current) {
        trailRef.current.setLatLngs(positionsRef.current);
      } else {
        trailRef.current = L.polyline(positionsRef.current, {
          color:     '#f0c040',
          weight:    1.5,
          opacity:   0.55,
          dashArray: '3 7',
        }).addTo(map);
      }
    } catch {
      // ignore (rate limit, network)
    }
  }, [map, enabled]);

  useEffect(() => {
    if (!enabled) { clearAll(); return; }

    let cancelled = false;
    let timer: ReturnType<typeof setTimeout>;

    const tick = async () => {
      await fetchAndRender();
      if (!cancelled) timer = setTimeout(tick, REFRESH_MS);
    };
    tick();

    return () => { cancelled = true; clearTimeout(timer); clearAll(); };
  }, [enabled, fetchAndRender, clearAll]);

  return null;
}
